import{_ as o,l as s,o as e,c as l,v as r,p as n,x as t,d,i as h,S as c}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"生物识别 FAR / FRR","description":"","frontmatter":{"title":"生物识别 FAR / FRR","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/biometrics-far-frr.md","filePath":"cs/biometrics-far-frr.md","lastUpdated":1789023840000}'),p={name:"cs/biometrics-far-frr.md"};function A(f,a,E,R,_,m){const i=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="生物识别-far-frr" tabindex="-1">生物识别 FAR / FRR <a class="header-anchor" href="#生物识别-far-frr" aria-label="Permalink to &quot;生物识别 FAR / FRR&quot;">​</a></h1><div class="epigraph"><p>生物识别是测量不是口令：假接受率与假拒绝率对调，阈值决定你把谁当成谁。模板泄漏不可像口令那样作废再选一个新拇指。</p><footer>—— 据 Jain, Ross and Prabhakar 对生物识别的综述；NIST 生物识别测试报告；对照 800-63B 对生物作为因素的限制</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/password-cracking">密码破解</a>还能轮换秘密。缺口是<strong>身体测量</strong>：FAR（陌生人当本人）与 FRR（本人被拒）。WebAuthn 课已说模板宜留在认证器；本课定量直觉。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>口令相等比较是精确的。生物是分数与阈值。人口大时，即使很小的 FAR 也会产生假匹配。缺口是错误率与威胁模型（呈现攻击、模板存储），不是传感器电路。</p><h3 id="不可作废" tabindex="-1">不可作废 <a class="header-anchor" href="#不可作废" aria-label="Permalink to &quot;不可作废&quot;">​</a></h3><p>种子可换，指纹难换。泄漏的模板要当长期凭证事故，配合设备密钥与衰减。</p><p><span class="marginnote">ISO/IEC 19795 测试方法点名。本课不写欺骗传感器的步骤。PAD（呈现攻击检测）只当需求点名。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画 ROC：阈值左移 FAR 降、FRR 升。对照：解锁手机是本机一对一；一对多识别是另一游戏。服务器不要收原始模板。</p>',12)),(e(),n(c,null,{default:t(()=>[h(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20SCORE%5B%22%E5%8C%B9%E9%85%8D%E5%88%86%E6%95%B0%22%5D%20--%3E%20TH%5B%22%E9%98%88%E5%80%BC%22%5D%0A%20%20TH%20--%3E%20FAR%5B%22%E5%81%87%E6%8E%A5%E5%8F%97%22%5D%0A%20%20TH%20--%3E%20FRR%5B%22%E5%81%87%E6%8B%92%E7%BB%9D%22%5D%0A%20%20TPL%5B%22%E6%A8%A1%E6%9D%BF%22%5D%20--%3E%20LOC%5B%22%E5%AE%9C%E7%95%99%E8%AE%A4%E8%AF%81%E5%99%A8%E5%86%85%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>MFA 里生物常是「本地解锁认证器」，服务器只看见 WebAuthn 成功。把生物当远程共享秘密会复制口令问题且更难轮换。下一课用形式工具看协议：ProVerif/Tamarin。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不评某厂商 FAR 广告数字。协议形式化下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>口令可轮换；生物是带错误率的测量。</li><li>FAR/FRR 随阈值对调；大规模一对多更险。</li><li>模板宜留在认证器，配合 WebAuthn。</li><li>下一课：协议形式化。</li><li>出处：Jain, Ross and Prabhakar；NIST 生物识别评估；NIST SP 800-63B。</li></ul>',8))])}const F=o(p,[["render",A]]);export{b as __pageData,F as default};
